//! Phase 18D-1 oracle: the Rust crew engine must reproduce the Go engine's CLI
//! output byte for byte for the whole corpus.
//!
//! Goldens are generated by `scripts/crew-host-oracle.py` (which runs the Go
//! `forseti-crew validate -f FILE --explain`) and live in
//! `host/tests/golden/<kind>/<crew>.json`. This test is the Rust half: it
//! replays every record through `forseti_host::crew::validate` and diffs
//! stdout / stderr / exit.

use std::path::{Path, PathBuf};

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("host/ has a parent")
        .to_path_buf()
}

#[test]
fn rust_engine_matches_go_goldens() {
    let root = repo_root();
    let golden = root.join("host/tests/golden");

    // Goldens record the corpus paths relative to the repo root, because that
    // is the argument the Go CLI was given — run the Rust engine from there.
    std::env::set_current_dir(&root).expect("chdir repo root");

    let mut files: Vec<PathBuf> = Vec::new();
    collect(&golden, &mut files);
    files.sort();
    assert!(!files.is_empty(), "no goldens under {}", golden.display());

    let mut failures: Vec<String> = Vec::new();
    for path in &files {
        let text = std::fs::read_to_string(path).expect("read golden");
        let rec: serde_json::Value = serde_json::from_str(&text).expect("parse golden");
        let rel = path
            .strip_prefix(&root)
            .unwrap_or(path)
            .display()
            .to_string();

        let file = rec["file"].as_str().expect("golden .file");
        let exit = rec["exit"].as_i64().expect("golden .exit") as i32;
        let stdout = rec["stdout"].as_str().expect("golden .stdout");
        let stderr = rec["stderr"].as_str().expect("golden .stderr");
        let explain = rec["argv"]
            .as_array()
            .map(|a| a.iter().any(|v| v == "--explain"))
            .unwrap_or(false);

        let got = forseti_host::crew::validate(file, explain);
        if got.stdout != stdout {
            failures.push(format!(
                "{rel}: stdout\n  want {stdout:?}\n  got  {:?}",
                got.stdout
            ));
        }
        if got.stderr != stderr {
            failures.push(format!(
                "{rel}: stderr\n  want {stderr:?}\n  got  {:?}",
                got.stderr
            ));
        }
        if got.exit != exit {
            failures.push(format!("{rel}: exit want {exit} got {}", got.exit));
        }
    }
    assert!(
        failures.is_empty(),
        "{} golden mismatch(es):\n{}",
        failures.len(),
        failures.join("\n")
    );
}

fn collect(dir: &Path, out: &mut Vec<PathBuf>) {
    for entry in std::fs::read_dir(dir).unwrap_or_else(|e| panic!("read {}: {e}", dir.display())) {
        let p = entry.expect("dir entry").path();
        if p.is_dir() {
            collect(&p, out);
        } else if p.extension().is_some_and(|e| e == "json") {
            out.push(p);
        }
    }
}
